function [A, B] = lin_model(u, P)
%LIN_MODEL  Linear single-track tractor-semitrailer model at constant speed u (m/s).
%  Generated by derive.py.  x = [v1; r1; phid; phi], inputs [M1; M2; delta]
%  v1 tractor lateral velocity (m/s), r1 tractor yaw rate (rad/s), phi articulation angle (rad)
%  M1, M2 control yaw moments on tractor and semitrailer (N m), delta front steer angle (rad)
  m1=P.m1; I1=P.I1; m2=P.m2; I2=P.I2; a1=P.a1; b1=P.b1; c1=P.c1; d2=P.d2; e2=P.e2;
  Cf=P.Cf; Cr=P.Cr; Ct=P.Ct;
  w0 = I1.*I2;
  w1 = Cf.*w0;
  w2 = d2.^2;
  w3 = I1.*m2;
  w4 = w2.*w3;
  w5 = Cf.*w4;
  w6 = c1.^2;
  w7 = I2.*m2;
  w8 = w6.*w7;
  w9 = Cf.*w8;
  w10 = a1.*w7;
  w11 = Cf.*w10;
  w12 = c1.*w11;
  w13 = -Cr.*I2.*b1.*c1.*m2 + w12;
  w14 = m1.*w0;
  w15 = m2.*w0;
  w16 = I1.*m1;
  w17 = m2.*w2;
  w18 = w16.*w17;
  w19 = I2.*m1;
  w20 = m2.*w6;
  w21 = w19.*w20;
  w22 = 1./(w14 + w15 + w18 + w21);
  w23 = w22./u;
  w24 = u.^2;
  w25 = e2.*w3;
  w26 = Ct.*w25;
  w27 = d2.*w26;
  w28 = a1.^2;
  w29 = c1.*w7;
  w30 = Cf.*w29;
  w31 = b1.^2;
  w32 = Cr.*w29;
  w33 = e2.^2;
  w34 = w3.*w33;
  w35 = Ct.*w34;
  w36 = I2.*d2;
  w37 = I2.*e2;
  w38 = -d2.*m2.*w33 - e2.*m2.*w2 + w36 + w37;
  w39 = I2 - d2.*e2.*m2;
  w40 = Ct.*w22;
  w41 = a1.*w19;
  w42 = d2.*m2;
  w43 = e2.*w42;
  w44 = c1.*m1;
  w45 = w43.*w44;
  w46 = m1.*w17;
  w47 = a1.*w46;
  w48 = Cf.*w41 + Cf.*w47 - Cr.*I2.*b1.*m1 - Cr.*I2.*b1.*m2 - Cr.*b1.*m1.*m2.*w2 - Ct.*I2.*c1.*m1 + Ct.*w45 + w11 + w30 + w32;
  w49 = Cf.*w28;
  w50 = w19.*w49;
  w51 = w49.*w7;
  w52 = Cr.*w31;
  w53 = w19.*w52;
  w54 = w52.*w7;
  w55 = Ct.*w6;
  w56 = w19.*w55;
  w57 = w46.*w49;
  w58 = w46.*w52;
  w59 = Ct.*w36.*w44;
  w60 = Ct.*w37.*w44;
  w61 = Ct.*w23;
  w62 = d2.*w16;
  w63 = Ct.*w62;
  w64 = e2.*w16;
  w65 = Ct.*w64;
  w66 = m1.*w20;
  w67 = e2.*w66;
  w68 = w42.*w44;
  w69 = a1.*w68;
  w70 = d2.*w3;
  w71 = Cr.*b1;
  w72 = w16.*w2;
  w73 = w16.*w33;
  w74 = 2*e2;
  w75 = w33.*w42.*w44;
  w76 = e2.*w17.*w44;
  w77 = w33.*w66;
  w78 = m1.*w43;
  w79 = Cf.*w22;
  w80 = w19 + w46 + w7;
  w81 = w10 + w29 + w41 + w47;
  A = zeros(4,4); B = zeros(4,3);
  A(1,1) = w23.*(-Cr.*w0 - Cr.*w4 - Cr.*w8 + Ct.*I1.*d2.*e2.*m2 - Ct.*w0 - w1 - w13 - w5 - w9);
  A(1,2) = w23.*(Cr.*I1.*I2.*b1 + Cr.*I1.*b1.*m2.*w2 + Cr.*I2.*b1.*m2.*w6 + Ct.*I1.*I2.*c1 + Ct.*I1.*I2.*d2 + Ct.*I1.*I2.*e2 - a1.*w1 - a1.*w5 - a1.*w9 - c1.*w27 - d2.*w35 - w14.*w24 - w15.*w24 - w18.*w24 - w2.*w26 - w21.*w24 - w28.*w30 - w31.*w32);
  A(1,3) = -Ct.*I1.*w23.*w38;
  A(1,4) = -I1.*w39.*w40;
  B(1,1) = w22.*w29;
  B(1,2) = w22.*w70;
  B(1,3) = w79.*(c1.*w10 + w0 + w4 + w8);
  A(2,1) = -w23.*w48;
  A(2,2) = w23.*(Ct.*c1.*d2.*m1.*m2.*w33 + Ct.*c1.*e2.*m1.*m2.*w2 + Ct.*d2.*e2.*m1.*m2.*w6 - w13 - w50 - w51 - w53 - w54 - w56 - w57 - w58 - w59 - w60);
  A(2,3) = w38.*w44.*w61;
  A(2,4) = w39.*w40.*w44;
  B(2,1) = w22.*w80;
  B(2,2) = -w22.*w68;
  B(2,3) = w79.*w81;
  A(3,1) = w23.*(Cf.*I1.*d2.*m2 - Cf.*w69 + Cr.*I1.*d2.*m2 + Cr.*b1.*c1.*d2.*m1.*m2 - Ct.*w67 - w26 - w48 - w63 - w65);
  A(3,2) = w23.*(Cf.*a1.*w70 + Ct.*c1.^3.*e2.*m1.*m2 + Ct.*w72 + Ct.*w73 + Ct.*w75 + Ct.*w76 + Ct.*w77 + c1.*w26 + c1.*w63 + c1.*w65 - w12 + w27 + w29.*w71 + w35 - w49.*w68 - w50 - w51 - w52.*w68 - w53 - w54 + 2*w55.*w78 - w56 - w57 - w58 - w59 - w60 + w63.*w74 - w70.*w71);
  A(3,3) = w61.*(I2.*c1.*d2.*m1 + I2.*c1.*e2.*m1 - d2.*w25 - w34 - w6.*w78 - w62.*w74 - w72 - w73 - w75 - w76 - w77);
  A(3,4) = w40.*(I2.*c1.*m1 - w25 - w45 - w62 - w64 - w67);
  B(3,1) = w22.*(w68 + w80);
  B(3,2) = w22.*(-w16 - w3 - w66 - w68);
  B(3,3) = w79.*(w69 - w70 + w81);
  A(4,1) = 0;
  A(4,2) = 0;
  A(4,3) = 1;
  A(4,4) = 0;
  B(4,1) = 0;
  B(4,2) = 0;
  B(4,3) = 0;
end
